# 다음 한 달을 어디에 쓸까 — 오차 숫자로 편향/분산을 가른다
def diagnose(human, train, dev):
    bias, var = train - human, dev - train          # 회피 가능 편향, 분산
    if max(bias, var) < 0.01:
        return "둘 다 작다: 배포 데이터와의 차이(분포 이동)를 보라"
    if bias >= var:
        return f"편향 {bias:.1%} 우세: 더 큰 모델·더 오래 학습 (데이터 추가는 효과 적다)"
    return f"분산 {var:.1%} 우세: 데이터 추가·정규화·증강"
for case in [(0.005, 0.01, 0.11), (0.005, 0.15, 0.16), (0.005, 0.08, 0.20), (0.005, 0.01, 0.015)]:
    print(case, "->", diagnose(*case))
